def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        return 'C' if history[1][1] == 'C' else 'D'

    opp_last = history[-1][1]
    my_last = history[-1][0]

    if n == 99:
        return 'D'

    total_opp_c = sum(1 for a, b in history if b == 'C')
    total_opp_d = n - total_opp_c
    total_my_c = sum(1 for a, b in history if a == 'C')
    total_my_d = n - total_my_c

    # Planned late probe against never-punishing cooperators.
    if total_opp_c == n:
        if n >= 82 and total_my_d > 0:
            return 'D'
        if n == 80 and total_my_d == 0:
            return 'D'
        if n == 81 and total_my_d == 1 and my_last == 'D' and opp_last == 'C':
            return 'C'
        return 'C'

    if total_opp_d == n:
        return 'D'

    recent_opp = [history[i][1] for i in range(max(0, n - 10), n)]
    recent_my = [history[i][0] for i in range(max(0, n - 5), n)]
    opp_c = recent_opp.count('C')
    opp_d = len(recent_opp) - opp_c
    recent_my_d = len(recent_my) - recent_my.count('C')

    streak_d = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        streak_d += 1
        i -= 1

    bad_recent = 0
    start_bad = max(1, n - 10)
    for i in range(start_bad, n):
        if history[i][1] == 'D' and history[i - 1][0] == 'C':
            bad_recent += 1

    if opp_d >= 7:
        return 'D'

    if total_opp_d >= total_opp_c + 3:
        return 'D'

    if opp_last == 'D':
        if streak_d >= 3:
            return 'D'

        # If we just defected, their D is likely a response; try to restore
        # cooperation against mostly nice opponents, but not persistent punishers.
        if recent_my_d == 0:
            return 'D'

        if total_opp_c >= total_opp_d + 3 and opp_c >= opp_d and bad_recent <= 1:
            return 'C'

        if total_opp_c >= total_opp_d + 10 and opp_c >= opp_d and bad_recent == 0:
            return 'C'

        return 'D'

    if my_last == 'D':
        if total_opp_c >= total_opp_d + 3 and opp_c >= opp_d:
            return 'C'
        return 'D'

    if opp_c >= opp_d:
        return 'C'

    if total_opp_c >= total_opp_d + 5:
        return 'C'

    if rng.random() < 0.1:
        return 'C'

    return 'D'
